<template><div class="page"><header><h2>我的任务</h2><p>仅展示已选课程中已发布的任务</p></header><p v-if="message" class="error">{{ message }}</p><section class="list"><article v-for="t in tasks" :key="t.taskId"><div><small>{{ t.courseName }} · {{ t.taskNo }}</small><h3>{{ t.taskTitle }}</h3><p>截止 {{ fmt(t.deadline) }}</p></div><span :class="deadlineClass(t.deadline)">{{ submissionLabel(submissions[t.taskId]) }}</span><button @click="open(t.taskId)">{{ submissions[t.taskId]?'查看 / 再次提交':'提交任务' }}</button></article><div v-if="tasks.length===0" class="empty">暂无已发布任务</div></section><teleport to="body"><div v-if="dialog&&detail" class="overlay" @click.self="dialog=false"><section class="modal"><h3>{{ detail.taskTitle }}</h3><p class="content">{{ detail.taskContent }}</p><div class="meta">截止 {{ fmt(detail.deadline) }} · {{ submitTypeLabel(detail.submitType) }} · 最大 {{ detail.maxFileSize }} MB</div><div v-if="current" class="submitted"><strong>最近一次提交</strong><p>{{ current.contentText||'无文本内容' }}</p><a v-if="current.attachments" :href="current.attachments" target="_blank">查看附件</a><span>{{ fmt(current.submittedAt) }}{{ current.isLate===1?' · 迟交':'' }}</span><em v-if="current.returnedReason">退回原因：{{ current.returnedReason }}</em></div><label v-if="detail.submitType!==2">文本内容<textarea v-model.trim="form.contentText" rows="5"/></label><label v-if="detail.submitType!==1">附件地址<input v-model.trim="form.attachments" placeholder="https://..."/></label><p v-if="formError" class="error">{{ formError }}</p><footer><button @click="dialog=false">关闭</button><button class="primary" @click="submit">{{ current?'再次提交':'提交' }}</button></footer></section></div></teleport></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{getMySubmission,getTaskDetail,getTaskPage,submitTask,type SubmissionItem,type TaskDetail,type TaskListItem}from'../../utils/teachingApi';const tasks=ref<TaskListItem[]>([]),submissions=reactive<Record<number,SubmissionItem|undefined>>({}),detail=ref<TaskDetail|null>(null),current=ref<SubmissionItem|null>(null),dialog=ref(false),message=ref(''),formError=ref('');const form=reactive({contentText:'',attachments:''});const err=(e:unknown)=>e instanceof Error?e.message:'操作失败';const fmt=(v:string)=>v?.replace('T',' ').slice(0,16)||'—';const submitTypeLabel=(v:number)=>({1:'文本提交',2:'文件提交',3:'文本与文件'}as Record<number,string>)[v];const submissionLabel=(s?:SubmissionItem)=>!s?'未提交':s.submitStatus===2?'已退回':'已提交';const deadlineClass=(v:string)=>new Date(v)<new Date()?'late':'normal';async function load(){try{tasks.value=(await getTaskPage({pageNum:1,pageSize:500})).records;await Promise.all(tasks.value.map(async t=>{try{submissions[t.taskId]=await getMySubmission(t.taskId)}catch{submissions[t.taskId]=undefined}}))}catch(e){message.value=err(e)}}async function open(id:number){try{detail.value=await getTaskDetail(id);current.value=submissions[id]||null;form.contentText=current.value?.contentText||'';form.attachments=current.value?.attachments||'';formError.value='';dialog.value=true}catch(e){message.value=err(e)}}async function submit(){if(!detail.value)return;if(detail.value.submitType===1&&!form.contentText||detail.value.submitType===2&&!form.attachments||detail.value.submitType===3&&!form.contentText&&!form.attachments){formError.value='请按任务要求填写提交内容';return}try{const s=await submitTask(detail.value.taskId,{contentText:form.contentText||undefined,attachments:form.attachments||undefined});submissions[detail.value.taskId]=s;current.value=s;message.value='任务提交成功';dialog.value=false}catch(e){formError.value=err(e)}}onMounted(load);
</script><style scoped>.page{height:100%;overflow:auto;padding:28px 36px;background:transparent;color:#172033}header h2{margin:0}header p{color:#7b8495}.list{display:flex;flex-direction:column;gap:10px;margin-top:18px}.list article{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:16px;padding:16px 18px;background:#fff;border:1px solid #e7ebf1;border-radius:12px}.list h3{margin:5px 0}.list small,.list p{color:#7b8495;font-size:12px}.list button,.modal footer button{border:0;border-radius:7px;padding:8px 11px;background:#eef1f6}.normal{color:#1d4ed8}.late{color:#b42336}.empty{text-align:center;padding:60px;color:#8992a2}.error{color:#b42336}.overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;background:#0f172a6b}.modal{width:min(620px,90%);max-height:85vh;overflow:auto;padding:22px;background:#fff;border-radius:14px}.content{white-space:pre-wrap}.meta{padding:10px;background:transparent;color:#687386;font-size:12px}.submitted{display:flex;flex-direction:column;gap:6px;margin:14px 0;padding:13px;border:1px solid #dce7fa;border-radius:9px;font-size:13px}.submitted span,.submitted em{color:#7b8495;font-size:12px}.modal label{display:flex;flex-direction:column;gap:6px;margin-top:14px;font-size:12px;color:#687386}.modal textarea,.modal input{border:1px solid #dfe4ec;border-radius:8px;padding:9px;font:inherit}.modal footer{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.primary{background:#2563eb!important;color:#fff!important}@media(max-width:650px){.list article{grid-template-columns:1fr;align-items:flex-start}}</style>
